Here's a Python program that meets your requirements. This program uses a dictionary to store the phonebook and allows users to add, remove, and search for phone numbers by name.

```python
# Initialize empty phonebook dictionary
phonebook = {}

def add_entry(name, number):
    """Add a new entry to the phonebook with the given name and number."""
    if name in phonebook:
        print(f"{name} is already in the phonebook. Number not updated.")
    else:
        phonebook[name] = number
        print(f"{name} added to the phonebook. Number: {number}")

def remove_entry(name):
    """Remove an entry from the phonebook with the given name."""
    if name in phonebook:
        del phonebook[name]
        print(f"{name} removed from the phonebook.")
    else:
        print(f"{name} not found in the phonebook.")

def search_entry(name):
    """Search for an entry in the phonebook with the given name and return the number."""
    if name in phonebook:
        return f"{name}: {phonebook[name]}"
    else:
        return f"{name} not found in the phonebook."

# Main program loop
while True:
    user_input = input("\nEnter 'add' to add a new entry, 'remove' to remove an entry, 'search' to search for an entry, or 'quit' to exit: ").lower()

    if user_input == 'add':
        name = input("Enter the name: ")
        number = input("Enter the number: ")
        add_entry(name, number)

    elif user_input == 'remove':
        name = input("Enter the name to remove: ")
        remove_entry(name)

    elif user_input == 'search':
        name = input("Enter the name to search for: ")
        print(search_entry(name))

    elif user_input == 'quit':
        break

    else:
        print("Invalid input. Please try again.")

print("Goodbye!")
```

This program will print the phonebook entries in the format "Name: Number" when a search is performed.
